INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 13, 'theory', 'Quiz: containers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 0, 'What is a container from the point of view of the Linux kernel?', '["A virtual machine with its own kernel", "Ordinary processes in a set of namespaces and control groups; there is no separate \"container\" entity in the kernel", "A special type of filesystem", "A process started as root"]', 1, 'Isolation is built from namespaces (visibility) and cgroups (consumption) of the host''s shared kernel.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 1, 'What number does the first process in a new PID namespace get?', '["Zero", "The same as on the host", "A random one", "One, and it is responsible for adopting orphans"]', 3, 'On the host this same process has a different number: one task, two names in two worlds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 2, 'What is the user namespace for?', '["So that users can log in to the system faster", "To encrypt home directories", "So that root inside the container maps to an ordinary user on the host", "To restrict passwords"]', 2, 'This is how rootless containers work: an escape gives only the rights of an unprivileged uid.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 3, 'What does cpu.max = "50000 100000" mean in cgroup v2?', '["No more than 50 ms of CPU time per every 100 ms: half a core", "No more than 50,000 processes", "No more than 100,000 open files", "Priority 50 out of 100"]', 0, 'The quota is given as a pair "allowed, period" in microseconds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 4, 'What happens when a file from a lower image layer is changed in overlayfs?', '["The lower layer itself is edited", "The file is deleted from the image", "The container stops", "The file is first copied to the upper writable layer (copy-up), and the edit goes on there"]', 3, 'Thanks to this, a hundred containers share image layers and keep only thin writable additions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 5, 'How does a container fundamentally differ from a virtual machine?', '["A container has its own kernel and device emulation", "A container uses the host''s shared kernel, and isolation comes from namespaces and cgroups", "A container runs on only one processor", "A container cannot isolate the network"]', 1, 'That is why containers start in a fraction of a second and have almost no overhead, but a kernel vulnerability affects everyone.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 6, 'What do cgroups limit, as opposed to namespaces?', '["Resources: CPU, memory, I/O and number of processes; namespaces limit what a process sees", "Visibility of files and processes", "Network access by address", "File owner rights"]', 0, 'Namespaces answer the question "what is visible", control groups answer "how much is allowed".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 13, 7, 'Why is root inside a container with a user namespace not equal to host root?', '["Root inside the container has no rights at all", "Host root is forbidden inside the container", "IDs are mapped: zero inside corresponds to an ordinary unprivileged one outside", "The host kernel ignores permission checks"]', 2, 'So the process looks like an administrator to itself and has no rights outside the container.');
